package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Beta.Threads.Runs.Steps.List(
		context.TODO(),
		"thread_id",
		"run_id",
		openai.BetaThreadRunStepListParams{
			Limit: param.NewOpt[int64](20),
			Order: param.NewOpt[openai.BetaThreadsRunsStepsListOrder](openai.BetaThreadsRunsStepsListOrderAsc),
			After: param.NewOpt[string]("after"),
			Before: param.NewOpt[string]("before"),
			Include: []string{"step_details.tool_calls[*].file_search.results[*].content"},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
